// Polyris Console — Runtime Configuration (DEPLOYED site)
//
// This file is for the deployed site. In production ui/deploy.sh (a.k.a.
// sam/deploy-ui.sh) OVERWRITES it with the real API Gateway URL and Cognito
// settings from CloudFormation outputs (API_URL = the ConsoleApiUrl output + "/api").
//
// For LOCAL development (`npm run dev`) do NOT edit this file — set
// ui/.env.local instead, and leave the values below at their fall-through defaults:
//   NEXT_PUBLIC_API_URL=https://<id>.execute-api.<region>.amazonaws.com/<stage>/api
//   NEXT_PUBLIC_AUTH_ENABLED=true|false
//   NEXT_PUBLIC_COGNITO_USER_POOL_ID / _CLIENT_ID / _REGION  (when auth is on)
// The empty API_URL and null AUTH.enabled here fall through to those env vars
// (config.ts uses `w.API_URL || env` and `w.AUTH.enabled ?? env`), so .env wins
// locally; window.CONFIG only wins when this file carries a real value (ADR #94).
//
// Whichever you set, API_URL must include BOTH the stage and the trailing /api
// (e.g. https://abc123.execute-api.us-east-1.amazonaws.com/dev/api) — the app
// appends route paths without /api.
//
window.CONFIG = {
    API_URL: '',
    POLL_INTERVAL: 30000,
    AUTH: {
        // null (NOT false): config.ts resolves `enabled` with `?? env`, so a
        // literal false here would OVERRIDE NEXT_PUBLIC_AUTH_ENABLED from .env and
        // silently disable auth in local dev. null lets .env drive it. deploy.sh
        // writes the real boolean for the deployed site.
        enabled: null,
        userPoolId: '',
        clientId: '',
        region: 'us-east-1'
    }
};
